/* The friends' copy in open/ is generated by tools/build_open.py. These checks fail when the app changed and the copy
   was not rebuilt, or when the copy could reach Sharaf's storage, his sync server or his pictures. */
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('../../', import.meta.url));
const SOURCES = ['index.html', 'platform.js', 'leaf-engine.js', 'leaf-merge.js', 'sw.js', 'manifest.webmanifest', 'tools/build_open.py'];
const read = f => readFileSync(ROOT + f, 'utf8');

test('open/ is built from the current app (run: python3 tools/build_open.py)', () => {
  const h = createHash('sha256');
  for(const f of SOURCES){ h.update(f); h.update(readFileSync(ROOT + f)); }
  assert.equal(read('open/.source-hash').trim(), h.digest('hex').slice(0, 16));
});

test('the copy keeps its own storage and caches, never syncs, and carries no pictures of Sharaf', () => {
  const html = read('open/index.html'), sw = read('open/sw.js');
  assert.ok(html.indexOf('window.LEAF_OPEN = true') < html.indexOf('<script src="leaf-merge.js">'), 'the switch is set before the app loads');
  assert.match(html, /S\.setItem=function\(k,v\)\{ return s\.call\(this, P\+k, v\); \}/, 'every localStorage key gets its own prefix');
  assert.doesNotMatch(html, /Sharaf's training/);
  assert.match(read('open/platform.js'), /OPEN \? 'leaf-village-open' : 'leaf-village-local'/);
  assert.match(read('open/platform.js'), /available: !!M && !OPEN/, 'no sync in the copy');
  assert.match(sw, /const CACHE = 'leafopen-'/); assert.match(sw, /startsWith\('leafopen-'\)/); assert.doesNotMatch(sw, /OPEN-SKIP|startsWith\('leaf-'\)/);
  assert.match(read('sw.js'), /OPEN-SKIP/, 'the main worker leaves the copy alone');
  assert.equal(existsSync(ROOT + 'open/guests'), false, 'no forms');
  const files = sw.slice(sw.indexOf('const FILES'), sw.indexOf('];', sw.indexOf('const FILES'))).match(/"([^"]+)"/g).map(s => s.slice(1, -1));
  for(const f of files) if(f !== './') assert.ok(existsSync(ROOT + 'open/' + f), `${f} is in the copy`);
  assert.ok(!files.some(f => /guests\/|media\/[0-9a-f]{32}|cine-/.test(f)), 'none of Sharaf\'s media');
  assert.ok(readdirSync(ROOT + 'open/ranks').length >= 60);
});
